import { describe, expect, it } from "vitest";
import {
  Decimal,
  DecimalDivisionByZeroError,
  DecimalOverflowError,
  type RoundingMode,
} from "../../src/internal/decimal.js";
import vectors from "./decimal-dotnet-vectors.json" with { type: "json" };

/**
 * The vectors in `decimal-dotnet-vectors.json` are generated by evaluating
 * `System.Decimal` on .NET and serializing the results, so these assertions
 * compare against the reference implementation rather than against hand-written
 * expectations. Regenerate them if the .NET baseline moves.
 */

function parseOrThrow(input: string): Decimal {
  const parsed = Decimal.parse(input);
  if (parsed === null) throw new Error(`Vector operand is unparsable: ${input}`);
  return parsed;
}

function apply(left: Decimal, op: string, right: Decimal): Decimal {
  switch (op) {
    case "+":
      return left.plus(right);
    case "-":
      return left.minus(right);
    case "*":
      return left.times(right);
    case "/":
      return left.dividedBy(right);
    default:
      throw new Error(`Unknown operator: ${op}`);
  }
}

describe("Decimal against .NET System.Decimal vectors", () => {
  const arithmetic = vectors.arithmetic as string[][];

  it("covers the generated arithmetic vectors", () => {
    expect(arithmetic.length).toBeGreaterThan(2000);
  });

  it("matches .NET for every arithmetic vector", () => {
    const failures: string[] = [];

    for (const [a, op, b, expected] of arithmetic) {
      const left = parseOrThrow(a!);
      const right = parseOrThrow(b!);

      let actual: string;
      try {
        actual = apply(left, op!, right).toString();
      } catch (error) {
        if (error instanceof DecimalDivisionByZeroError) actual = "DIVZERO";
        else if (error instanceof DecimalOverflowError) actual = "OVERFLOW";
        else throw error;
      }

      if (actual !== expected) failures.push(`${a} ${op} ${b} => ${actual}, expected ${expected}`);
    }

    expect(failures).toEqual([]);
  });

  it("matches .NET Math.Round for every rounding vector", () => {
    const failures: string[] = [];

    for (const [value, decimals, mode, expected] of vectors.rounding as string[][]) {
      const actual = parseOrThrow(value!)
        .round(Number(decimals), mode as RoundingMode)
        .toString();
      if (actual !== expected) {
        failures.push(`round(${value}, ${decimals}, ${mode}) => ${actual}, expected ${expected}`);
      }
    }

    expect(failures).toEqual([]);
  });

  it("matches .NET decimal.Parse for every parsing vector", () => {
    const failures: string[] = [];

    for (const [input, expected] of vectors.parsing as string[][]) {
      const parsed = Decimal.parse(input!);
      const actual = parsed === null ? "OVERFLOW" : parsed.toString();
      if (actual !== expected) failures.push(`parse(${input}) => ${actual}, expected ${expected}`);
    }

    expect(failures).toEqual([]);
  });
});

describe("Decimal.parse", () => {
  it.each(["", " ", "abc", "1.2.3", "1e3", ".5", "5.", "1,5", "--1", "+-1"])(
    "rejects %j",
    (input) => {
      expect(Decimal.parse(input)).toBeNull();
    },
  );

  it("preserves trailing zeros as significant scale", () => {
    expect(Decimal.parse("12.750")!.toString()).toBe("12.750");
  });
});

describe("Decimal unit conversion", () => {
  // The case that rules out binary floating point: in doubles this is
  // 0.9144000000000001, which would leak into normalize() output.
  it("multiplies conversion factors exactly", () => {
    const feet = Decimal.parse("3")!;
    const factor = Decimal.parse("0.3048")!;
    expect(feet.times(factor).toTrimmedString()).toBe("0.9144");
  });

  it("round-trips through the base unit", () => {
    const inches = Decimal.parse("7")!;
    const factor = Decimal.parse("0.0254")!;
    const meters = inches.times(factor);

    expect(meters.toTrimmedString()).toBe("0.1778");
    expect(meters.dividedBy(factor).toTrimmedString()).toBe("7");
  });

  it("divides at the precision .NET uses", () => {
    expect(Decimal.parse("1")!.dividedBy(Decimal.parse("0.0254")!).toString()).toBe(
      "39.370078740157480314960629921",
    );
  });
});

describe("Decimal comparison", () => {
  it("ignores scale", () => {
    expect(Decimal.parse("1.0")!.equals(Decimal.parse("1.00")!)).toBe(true);
    expect(Decimal.parse("1.0")!.compareTo(Decimal.parse("1.00")!)).toBe(0);
  });

  it.each([
    ["1", "2", -1],
    ["2", "1", 1],
    ["-1", "1", -1],
    ["0.0001", "0.001", -1],
  ])("compares %s to %s", (a, b, expected) => {
    expect(Decimal.parse(a)!.compareTo(Decimal.parse(b)!)).toBe(expected);
  });
});

describe("Decimal rendering", () => {
  it.each([
    ["12.750", "12.75"],
    ["1.00", "1"],
    ["0.9144", "0.9144"],
    ["100", "100"],
    ["-0.500", "-0.5"],
  ])("trims %s to %s", (input, expected) => {
    expect(Decimal.parse(input)!.toTrimmedString()).toBe(expected);
  });

  it("converts to number for consumer-facing accessors", () => {
    expect(Decimal.parse("0.9144")!.toNumber()).toBe(0.9144);
    expect(Decimal.parse("-12.5")!.toNumber()).toBe(-12.5);
  });
});

describe("Decimal errors", () => {
  it("throws on division by zero", () => {
    expect(() => Decimal.parse("1")!.dividedBy(Decimal.zero)).toThrow(DecimalDivisionByZeroError);
  });

  it("throws on overflow", () => {
    const max = Decimal.parse("79228162514264337593543950335")!;
    expect(() => max.times(Decimal.parse("1.1")!)).toThrow(DecimalOverflowError);
  });

  it("underflows to a scale-28 zero rather than throwing", () => {
    const tiny = Decimal.parse("0.0000000000000001")!;
    expect(tiny.times(tiny).toString()).toBe("0.0000000000000000000000000000");
  });
});
